.pagina-heredada .mkd-grid{
	width:inherit !important;
	padding-left:2.6rem;
	padding-right:2.6rem ;
}
@media (max-width: 767px){
.pagina-heredada .mkd-title-holder{
		display: none !important;
	}
}
@media (max-width: 767px){
.pagina-heredada img{
        width: 120%; 
    }
.pagina-heredada h1{
        margin: 10px;
    }
}
.pagina-heredada .mkd-title-holder{
    position: relative;
    overflow: hidden;
    margin-bottom: 30px !important;

    /* z-index solicitado */
    z-index: 1 !important;

    /* Padding vertical */
    padding-top: 90px !important;
    padding-bottom: 90px !important;

    /* Sin altura fija */
    height: auto !important;
    min-height: unset !important;
    max-height: unset !important;
}
.pagina-heredada .mkd-title-holder::before{
    content: "";
    position: absolute;
    inset: 0;
    background: rgba(35, 52, 101, 0.8);
    z-index: 1;
    pointer-events: none;
}
.pagina-heredada .mkd-title-holder .mkd-title-wrapper, .pagina-heredada .mkd-title-holder .mkd-title-inner{
    position: relative;
    z-index: 2;
}
.pagina-heredada .mkd-title-holder .mkd-title-wrapper{
    height: auto !important;
    padding: 0 !important;
}
.pagina-heredada .mkd-title-holder .mkd-title-inner{
    padding: 0 !important;
    margin: 0 !important;
}
@media (max-width: 767px){
.pagina-heredada .mkd-title-holder .mkd-title-wrapper, .pagina-heredada .mkd-title-holder .mkd-title-inner{
        display: flex !important;
        justify-content: center !important;
        align-items: center !important;
        text-align: center !important;
    }
}
.pagina-heredada header{
    position: relative !important;
    z-index: 9999 !important;
}
.pagina-heredada p{
    font-family: 'Montserrat', sans-serif !important;
}
.pagina-heredada h2{
    font-family: 'lato', sans-serif !important;
}
.pagina-heredada a{
    font-family: 'lato', sans-serif !important;
}
.pagina-heredada span{
    font-family: 'montserrat', sans-serif !important;
}
.pagina-heredada *, .pagina-heredada *::before, .pagina-heredada *::after{animation-duration:0s!important;animation-delay:0s!important;transition:none!important;caret-color:transparent!important}
.pagina-heredada .hfe-skip-link{position:absolute;left:-9999px;top:0;z-index:100000;padding:0.75em 1.5em;background:#fff;color:#0073aa;font-size:14px;text-decoration:underline;border-radius:0 0 3px 0;}
.pagina-heredada .hfe-skip-link:focus{left:0;outline:2px solid #0073aa;outline-offset:-2px;}
.pagina-heredada .fila-wpbakery{
        display: flex;
        justify-content: space-between;
        padding: 20px;
        max-width: 1200px;
        margin: 0 auto;
    }
.pagina-heredada .columna-wpbakery{
        flex: 1;
        margin: 0 10px;
        text-align: center;
        transition: all 0.3s ease;
    }
.pagina-heredada .imagen-contenedor-wpbakery{
        overflow: hidden;
        border-radius: 8px;
        margin-bottom: 15px;
    }
.pagina-heredada .columna-wpbakery img{
        width: 100%;
        max-width: 300px;
        height: auto;
        display: block;
        transition: transform 0.3s ease;
    }
.pagina-heredada .columna-wpbakery:hover img{
        transform: scale(1.05);
    }
.pagina-heredada .columna-wpbakery h2{
        color: #153A67;
        margin-top: 10px;
        transition: color 0.3s ease;
    }
.pagina-heredada .columna-wpbakery:hover h2{
        color: #1a4f8b;
    }
.pagina-heredada .columna-wpbakery a{
        text-decoration: none;
        color: inherit;
        display: block;
    }
@media (max-width: 1024px){
.pagina-heredada .fila-wpbakery{
        max-width: 900px;
    }
.pagina-heredada .columna-wpbakery{
        margin: 0 8px;
    }
.pagina-heredada .columna-wpbakery img{
        max-width: 250px;
    }
}
@media (max-width: 768px){
.pagina-heredada .fila-wpbakery{
        flex-wrap: wrap;
        justify-content: center;
        padding: 15px;
    }
.pagina-heredada .columna-wpbakery{
        flex: 0 0 calc(50% - 20px);
        margin: 10px;
    }
.pagina-heredada .columna-wpbakery img{
        max-width: 100%;
        margin: 0 auto;
    }
}
.pagina-heredada .joinchat{--ch:208;--cs:70%;--cl:33%;--bw:1}

