    height: auto !important;
    padding: 0 !important;
}
.pagina-heredada .mkd-title-holder .mkd-title-inner{
    padding: 0 !important;
    margin: 0 !important;
}
@media (max-width: 767px){
.pagina-heredada .mkd-title-holder .mkd-title-wrapper, .pagina-heredada .mkd-title-holder .mkd-title-inner{
        display: flex !important;
