.pagina-heredada *, .pagina-heredada *::before, .pagina-heredada *::after{
  margin:0;
  padding:0;
  box-sizing:border-box;
}
.pagina-heredada{
  scroll-behavior:smooth;
  overflow-x:hidden;
  width:100%;
}
.pagina-heredada{
  width:100%;
  max-width:100%;
  overflow-x:hidden !important;

  font-family:'Montserrat',sans-serif;

  background:#fff;
  color:#111;

  -webkit-font-smoothing:antialiased;
}
.pagina-heredada img{
  width:100%;
  max-width:100%;
  display:block;
  height:auto;
}
.pagina-heredada a{
  text-decoration:none;
  color:inherit;
}
.pagina-heredada section{
  width:100%;
  overflow:hidden;
  position:relative;
}
.pagina-heredada{

  --primary:#132E6A;
  --secondary:#94BDD5;
  --light:#D1D1CF;
  --white:#fff;
  --gray:#6f6f6f;
  --black:#111;

  --font-title:'Bebas Neue',sans-serif;
  --font-body:'Montserrat',sans-serif;

  --container:1280px;

  --radius:18px;

}
.pagina-heredada .container{
  width:100%;
  max-width:1280px;

  margin-inline:auto;

  padding-left:clamp(18px,5vw,60px);
  padding-right:clamp(18px,5vw,60px);
}
.pagina-heredada .reveal{
  opacity:0;
  transform:translateY(30px);
  transition:.7s ease;
}
.pagina-heredada .reveal.visible{
  opacity:1;
  transform:none;
}
.pagina-heredada .d2{transition-delay:.2s;}
.pagina-heredada .hero-nav{
  position:absolute;
  top:0;
  left:0;

  width:100%;

  z-index:50;

  padding:20px 0;
}
.pagina-heredada .hero-nav .container{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:20px;
}
.pagina-heredada .logo{
  font-family:var(--font-title);

  font-size:clamp(1.8rem,4vw,2.8rem);

  letter-spacing:2px;

  color:#fff;
}
.pagina-heredada .nav-links{
  display:flex;
  list-style:none;
  gap:24px;
}
.pagina-heredada .hero{
  min-height:100svh;

  display:flex;
  align-items:flex-end;

  padding-top:140px;
  padding-bottom:70px;
}
.pagina-heredada .hero-bg{
  position:absolute;
  inset:0;

  background-image:url("https://ofitodo.com/wp-content/uploads/2026/06/ChatGPT-Image-15-jun-2026_-09_47_36.webp");

  background-size:cover;
  background-position:center;

  z-index:0;
}
.pagina-heredada .hero-bg::after{
  content:'';

  position:absolute;
  inset:0;

  background:
  linear-gradient(
    to top,
    rgba(19,46,106,.97),
    rgba(19,46,106,.65),
    rgba(19,46,106,.20)
  );
}
.pagina-heredada .hero-content{
  position:relative;
  z-index:10;

  width:100%;
  max-width:850px;
}
.pagina-heredada .hero-tags{
  display:flex;
  flex-wrap:wrap;
  gap:10px;

  margin-bottom:22px;
}
.pagina-heredada .hero h1{
  font-family:var(--font-title);

  font-size:clamp(2.5rem,10vw,7rem);

  line-height:.9;

  color:#fff;

  margin-bottom:18px;

  overflow-wrap:break-word;
  word-break:break-word;
  hyphens:auto;
}
.pagina-heredada .hero p{
  font-size:clamp(.95rem,2vw,1.1rem);

  line-height:1.8;

  color:rgba(255,255,255,.82);

  margin-bottom:34px;

  max-width:650px;
}
.pagina-heredada .hero-buttons{
  display:flex;
  flex-wrap:wrap;
  gap:14px;
}
.pagina-heredada .btn{
  min-height:52px;

  padding:14px 28px;

  border-radius:10px;

  display:inline-flex;
  align-items:center;
  justify-content:center;

  text-align:center;

  font-size:12px;

  font-weight:700;

  text-transform:uppercase;

  letter-spacing:.08em;

  transition:.25s;

  border:2px solid transparent;
}
.pagina-heredada .primary{
  background:var(--secondary);
  color:var(--primary);
}
.pagina-heredada .primary:hover{
  background:#fff;
}
.pagina-heredada .outline{
  border-color:rgba(255,255,255,.45);
  color:#fff;
}
.pagina-heredada .outline:hover{
  background:rgba(255,255,255,.08);
  border-color:#fff;
}
.pagina-heredada .hero-number{
  position:absolute;

  right:3%;
  bottom:20px;

  font-family:var(--font-title);

  font-size:clamp(5rem,18vw,14rem);

  color:rgba(255,255,255,.05);

  line-height:1;
}
.pagina-heredada .about{
  padding:100px 0;
}
.pagina-heredada .grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:70px;
}
.pagina-heredada .section-label{
  display:block;

  margin-bottom:14px;

  font-size:11px;

  font-weight:700;

  text-transform:uppercase;

  letter-spacing:.2em;

  color:var(--secondary);
}
.pagina-heredada .about-title{
  font-family:var(--font-title);

  font-size:clamp(2.2rem,6vw,4.2rem);

  line-height:.95;

  color:var(--primary);

  margin-bottom:24px;

  overflow-wrap:break-word;
  word-break:break-word;
}
.pagina-heredada .about p{
  font-size:15px;

  line-height:1.9;

  color:var(--gray);

  margin-bottom:18px;
}
.pagina-heredada .gallery{
  background:var(--primary);

  padding:100px 0;
}
.pagina-heredada .gallery-header{
  display:flex;
  justify-content:space-between;
  align-items:flex-end;

  gap:20px;

  margin-bottom:34px;
}
.pagina-heredada .gallery-title{
  font-family:var(--font-title);

  font-size:clamp(2.5rem,6vw,4.5rem);

  line-height:.95;

  color:#fff;
}
.pagina-heredada .gallery-count{
  font-family:var(--font-title);

  font-size:clamp(2rem,5vw,4rem);

  color:rgba(255,255,255,.15);
}
.pagina-heredada .gallery-grid{
  display:grid;

  grid-template-columns:1.5fr 1fr;

  gap:14px;
}
.pagina-heredada .gallery-main, .pagina-heredada .gallery-small{
  border-radius:20px;
  overflow:hidden;
}
.pagina-heredada .gallery-main{
  min-height:600px;
}
.pagina-heredada .gallery-small{
  min-height:292px;
}
.pagina-heredada .gallery-main img, .pagina-heredada .gallery-small img{
  width:100%;
  height:100%;
  object-fit:cover;

  transition:transform .55s ease;
}
.pagina-heredada .gallery-main:hover img, .pagina-heredada .gallery-small:hover img{
  transform:scale(1.04);
}
.pagina-heredada .cta{
  background:var(--primary);

  padding:110px 0;
}
.pagina-heredada .cta-inner{
  display:grid;

  grid-template-columns:1fr auto;

  gap:60px;

  align-items:center;
}
.pagina-heredada .cta h2{
  font-family:var(--font-title);

  font-size:clamp(2.8rem,9vw,6rem);

  line-height:.92;

  color:#fff;

  margin-bottom:18px;

  overflow-wrap:break-word;
  word-break:break-word;
}
.pagina-heredada .cta h2 span{
  color:var(--secondary);
}
.pagina-heredada .cta-desc{
  font-size:15px;

  line-height:1.9;

  color:rgba(255,255,255,.78);

  margin-bottom:32px;

  max-width:560px;
}
.pagina-heredada .cta-buttons{
  display:flex;
  flex-wrap:wrap;
  gap:14px;
}
.pagina-heredada .btn-cta{
  background:var(--secondary);
  color:var(--primary);
}
.pagina-heredada .cta-contact{
  display:flex;
  flex-direction:column;
  gap:20px;
}
.pagina-heredada footer{
  background:#081530;
  padding:30px 0;
}
.pagina-heredada .footer-inner{
  display:flex;
  justify-content:space-between;
  align-items:center;

