.pagina-heredada .joinchat__close{--size:34px;position:absolute;top:calc(50% - var(--size)/2);right:24px;width:var(--size);height:var(--size);border-radius:50%;background:rgba(0,0,0,.4) url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' fill='%23fff' viewBox='0 0 24 24'%3E%3Cpath d='M24 2.4 21.6 0 12 9.6 2.4 0 0 2.4 9.6 12 0 21.6 2.4 24l9.6-9.6 9.6 9.6 2.4-2.4-9.6-9.6z'/%3E%3C/svg%3E") 50%/12px no-repeat;cursor:pointer;transition:background-color .3s ease-out}
.pagina-heredada .joinchat__close:hover{background-color:rgba(0,0,0,.6)}
.pagina-heredada .joinchat__close:active{background-color:rgba(0,0,0,.7)}
.pagina-heredada .joinchat__scroll{display:flex;flex-direction:column-reverse;overflow:hidden scroll;scroll-behavior:smooth;overscroll-behavior-y:contain;-webkit-overflow-scrolling:touch}
.pagina-heredada .joinchat__scroll::-webkit-scrollbar{width:4px;background:rgb(0 0 0/0)}
.pagina-heredada .joinchat__scroll::-webkit-scrollbar-thumb{border-radius:2px;background:rgb(0 0 0/0)}
.pagina-heredada .joinchat__scroll:hover::-webkit-scrollbar-thumb{background:rgba(0,0,0,.2)}
.pagina-heredada .joinchat__content{display:flex;flex-direction:column;width:calc(100% + 4px);padding:20px 0 8px}
.pagina-heredada .joinchat__content:after{content:"";display:block;position:absolute;bottom:0;left:0;right:4px;height:calc(var(--s) + 20px);background:#fff linear-gradient(180deg,var(--bg),var(--bg));-webkit-mask-image:linear-gradient(rgb(0 0 0/0),rgb(0 0 0/60%) 25%,rgb(0 0 0/92%) 70%,rgb(0 0 0/100%) 95%,rgb(0 0 0/100%));mask-image:linear-gradient(rgb(0 0 0/0),rgb(0 0 0/60%) 25%,rgb(0 0 0/92%) 70%,rgb(0 0 0/100%) 95%,rgb(0 0 0/100%));pointer-events:none}
.pagina-heredada .joinchat__open{position:sticky;z-index:2;bottom:8px;align-self:flex-end;display:flex;flex-direction:row;min-width:var(--s);height:var(--s);margin:0 8px;background:var(--color);color:inherit;border-radius:var(--h);box-shadow:0 1px 2px 0 rgba(0,0,0,.3);overflow:hidden;cursor:pointer;transition:background-color .2s linear}
.pagina-heredada .joinchat__open:active, .pagina-heredada .joinchat__open:hover{background:var(--hover)}
.pagina-heredada .joinchat__open__icon{flex-shrink:0;width:var(--s);height:var(--s);max-width:var(--s);padding:calc(var(--s)*0.18);margin:0;overflow:hidden}
.pagina-heredada .joinchat__open__icon path{fill:none!important;stroke:var(--text)!important;stroke-linecap:round;stroke-width:33px;animation:none}
.pagina-heredada .joinchat__open__icon .joinchat__pa{--stroke:1097}
.pagina-heredada .joinchat__open__icon .joinchat__pb{--stroke:1020}
.pagina-heredada .joinchat__open__text{--mw:0;max-width:var(--mw);width:-moz-fit-content;width:fit-content;padding:0;font-weight:600;line-height:var(--s);white-space:nowrap;opacity:0;overflow:hidden;text-overflow:ellipsis}
@keyframes joinchat_open_text{0%{max-width:0;opacity:0}60%{max-width:var(--mw);opacity:0}to{max-width:var(--mw);opacity:1}}
.pagina-heredada .joinchat__chat{--peak_l:path("M17 25V0C17 12.877 6.082 14.9 1.031 15.91c-1.559.31-1.179 2.272.004 2.272C9.609 18.182 17 18.088 17 25z");--peak_r:path("M0 25.68V0c0 13.23 10.92 15.3 15.97 16.34 1.56.32 1.18 2.34 0 2.34-8.58 0-15.97-.1-15.97 7Z");--peak:var(--peak_l);display:flex;flex-direction:column;align-items:flex-start;min-height:100px;padding-bottom:10px;transition:height .2s ease-out}
.pagina-heredada .joinchat__bubble{flex-shrink:0;position:relative;min-width:60px;max-width:calc(100% - 52px);min-height:56px;padding:15px 20px;margin:0 26px 16px;border-radius:26px;background:#fff;color:#4a4a4a;word-break:break-word;filter:drop-shadow(0 1px 2px rgba(0,0,0,.3));transform-origin:0 50%;animation:joinchat_show .22s cubic-bezier(0,0,.58,1.19) 10ms both}
.pagina-heredada .joinchat__bubble:before{content:"";display:block;position:absolute;bottom:18px;left:-15px;width:17px;height:25px;background:inherit;clip-path:var(--peak)}
.pagina-heredada .joinchat__header{anchor-name:--joinchat-header}
.pagina-heredada .joinchat__powered{position:absolute;position-anchor:--joinchat-header;position-area:bottom left;left:-75px;top:75px;width:130px;height:20px;padding:0;margin:0;background:#fff!important;color:#0009!important;border:none!important;border-radius:4px 4px 0 0!important;font:11px/20px var(--joinchat-font)!important;text-align:center!important;text-decoration:none!important;transition:color .2s ease-out;box-shadow:0 2px 6px 0 #0003!important;transform:rotate(-90deg);opacity:0}
@supports not (position-anchor:--x){
.pagina-heredada .joinchat__powered{display:none}
}
.pagina-heredada .joinchat__powered span{font-weight:600}
.pagina-heredada .joinchat__powered:active, .pagina-heredada .joinchat__powered:hover{color:#000!important;text-decoration:none!important}
@keyframes joinchat_show{0%{transform:scale3d(0,0,0)}to{transform:scaleX(1)}}
@keyframes joinchat_badge_in{0%{opacity:0;transform:translate3d(0,50px,0)}to{opacity:1;transform:translateZ(0)}}
@keyframes joinchat_badge_out{0%{opacity:1;transform:translateZ(0)}to{opacity:0;transform:translate3d(0,-20px,0)}}
@keyframes joinchat_send_svg{0%,50%,to{stroke-dashoffset:var(--stroke)}5%,45%{stroke-dashoffset:0}}
@keyframes joinchat_image_loop{0%{opacity:0}3%,20%{opacity:1}25%,to{opacity:0}}
@keyframes joinchat_tootlip{0%{opacity:0;transform:scaleY(0)}1%,20%{opacity:1;transform:scaleX(1)}25%,to{opacity:0;transform:scaleX(1)}}
@media (orientation:landscape) and (height <= 480px),(width <= 480px){
.pagina-heredada .joinchat{--sep:6px;--header:max(50px,var(--s)*0.9166667)}
.pagina-heredada .joinchat__close{--size:28px}
.pagina-heredada .joinchat__bubble{max-width:calc(100% - 40px);padding:16px;margin:0 20px 10px;line-height:24px}
.pagina-heredada .joinchat:has(.joinchat__powered) .joinchat__content{padding-top:40px}
.pagina-heredada .joinchat--right .joinchat__powered{position-area:bottom center;z-index:2;top:0;left:0;right:0;transform:none;border-radius:0 0 4px 4px}
}
@media (hover:hover){
.pagina-heredada .joinchat__button:hover .joinchat__tooltip{opacity:1;animation:none;transition:opacity .2s}
}
@media (prefers-reduced-motion){
.pagina-heredada .joinchat, .pagina-heredada .joinchat__open__icon path{animation:none}
.pagina-heredada .joinchat__open__icon .joinchat__pa{stroke-dasharray:0}
.pagina-heredada .joinchat__bubble{animation:none!important}
}
.pagina-heredada img:is([sizes=auto i],[sizes^="auto," i]){contain-intrinsic-size:3000px 1500px}
