.pagina-heredada .mkd-grid{
	width:inherit !important;
	padding-left:2.6rem;
	padding-right:2.6rem ;
}
@media (max-width: 767px){
.pagina-heredada .mkd-title-holder{
		display: none !important;
	}
}
@media (max-width: 767px){
.pagina-heredada img{
        width: 120%; 
    }
.pagina-heredada h1{
        margin: 10px;
    }
}
@media (max-width: 575px){
.pagina-heredada .entry-title.mkd-post-title a{
		font-size: 14px !important;
	}
}
.pagina-heredada .mkd-post-info-author-link{
	display: none;
}
.pagina-heredada .mkd-post-info-category{
	display:none;
}
.pagina-heredada .mkd-post-info-author-text{
	display: none;
}
.pagina-heredada .mkd-comment-form-inner{
	display:none;
}
.pagina-heredada .mkd-title-holder{
    position: relative;
    overflow: hidden;
    margin-bottom: 30px !important;

    /* z-index solicitado */
    z-index: 1 !important;

    /* Padding vertical */
    padding-top: 90px !important;
    padding-bottom: 90px !important;

    /* Sin altura fija */
    height: auto !important;
    min-height: unset !important;
    max-height: unset !important;
}
.pagina-heredada .mkd-title-holder::before{
    content: "";
    position: absolute;
    inset: 0;
    background: rgba(35, 52, 101, 0.8);
    z-index: 1;
    pointer-events: none;
}
.pagina-heredada .mkd-title-holder .mkd-title-wrapper, .pagina-heredada .mkd-title-holder .mkd-title-inner{
    position: relative;
    z-index: 2;
}
.pagina-heredada .mkd-title-holder .mkd-title-wrapper{
    height: auto !important;
    padding: 0 !important;
}
.pagina-heredada .mkd-title-holder .mkd-title-inner{
    padding: 0 !important;
    margin: 0 !important;
}
@media (max-width: 767px){
.pagina-heredada .mkd-title-holder .mkd-title-wrapper, .pagina-heredada .mkd-title-holder .mkd-title-inner{
        display: flex !important;
        justify-content: center !important;
        align-items: center !important;
        text-align: center !important;
    }
}
.pagina-heredada header{
    position: relative !important;
    z-index: 9999 !important;
}
.pagina-heredada p{
    font-family: 'Montserrat', sans-serif !important;
}
.pagina-heredada label{
    font-family: 'lato', sans-serif !important;
}
.pagina-heredada h2{
    font-family: 'lato', sans-serif !important;
}
.pagina-heredada a{
    font-family: 'lato', sans-serif !important;
}
.pagina-heredada span{
    font-family: 'montserrat', sans-serif !important;
}
.pagina-heredada h3{
    font-family: 'lato', sans-serif !important;
}
.pagina-heredada *, .pagina-heredada *::before, .pagina-heredada *::after{animation-duration:0s!important;animation-delay:0s!important;transition:none!important;caret-color:transparent!important}
.pagina-heredada .hfe-skip-link{position:absolute;left:-9999px;top:0;z-index:100000;padding:0.75em 1.5em;background:#fff;color:#0073aa;font-size:14px;text-decoration:underline;border-radius:0 0 3px 0;}
.pagina-heredada .hfe-skip-link:focus{left:0;outline:2px solid #0073aa;outline-offset:-2px;}
.pagina-heredada *, .pagina-heredada *::before, .pagina-heredada *::after{box-sizing:border-box;margin:0;padding:0}
.pagina-heredada{
    --navy:#0D2B52;
    --navy-mid:#1A4080;
    --blue-light:#E8F0FA;
    --orange:#2F6FED;
    --orange-dark:#1E4FC4;
    --orange-light:#E8F0FF;
    --white:#FFFFFF;
    --gray-50:#F8F9FB;
    --gray-100:#EEF1F6;
    --gray-400:#9BA8BB;
    --gray-700:#3D4D63;
    --text:#1A2A3D;
    --radius-sm:8px;
    --radius-md:14px;
    --radius-lg:20px;
  }
.pagina-heredada{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:var(--text);background:var(--white);line-height:1.6;font-size:16px}
.pagina-heredada .hero{background:var(--navy);color:var(--white);padding:48px 20px 52px;position:relative;overflow:hidden}
.pagina-heredada .hero::before{content:'';position:absolute;top:-60px;right:-40px;width:220px;height:220px;border-radius:50%;background:rgba(47,111,237,0.14);pointer-events:none}
.pagina-heredada .hero::after{content:'';position:absolute;bottom:-30px;left:-20px;width:140px;height:140px;border-radius:50%;background:rgba(255,255,255,0.04);pointer-events:none}
.pagina-heredada .hero-eyebrow{display:inline-block;background:var(--orange);color:var(--white);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;padding:5px 14px;border-radius:30px;margin-bottom:20px}
.pagina-heredada .hero-lead{font-size:15px;color:rgba(255,255,255,0.78);max-width:480px;margin-bottom:30px;line-height:1.7}
.pagina-heredada .hero-photo{width:100%;border-radius:var(--radius-md);overflow:hidden;margin-top:8px;background:var(--navy-mid);min-height:200px;display:flex;align-items:center;justify-content:center;border:1px solid rgba(255,255,255,0.1)}
.pagina-heredada .photo-placeholder{display:flex;flex-direction:column;align-items:center;gap:8px;color:rgba(255,255,255,0.35);font-size:13px;text-align:center;padding:32px 16px}
.pagina-heredada .section{padding:44px 20px}
.pagina-heredada .section-alt{background:var(--gray-50)}
.pagina-heredada .section-navy{background:var(--navy);color:var(--white)}
.pagina-heredada .label{font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--orange);margin-bottom:10px}
.pagina-heredada .label-white{color:rgba(255,255,255,0.7)}
.pagina-heredada .section-title{font-size:clamp(20px,5.5vw,28px);font-weight:800;line-height:1.2;margin-bottom:8px;color:var(--navy)}
.pagina-heredada .section-title-white{color:var(--white)}
.pagina-heredada .section-sub{font-size:14px;color:var(--gray-700);margin-bottom:32px;line-height:1.65;max-width:520px}
.pagina-heredada .section-sub-white{color:rgba(255,255,255,0.75)}
.pagina-heredada .cards-grid{display:grid;grid-template-columns:1fr;gap:16px}
@media(min-width:480px){
.pagina-heredada .cards-grid{grid-template-columns:1fr 1fr}
}
.pagina-heredada .card{background:var(--white);border:1.5px solid var(--gray-100);border-radius:var(--radius-md);padding:24px 20px;position:relative;overflow:hidden}
.pagina-heredada .card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:var(--orange)}
.pagina-heredada .card-icon{width:42px;height:42px;border-radius:var(--radius-sm);background:var(--orange-light);display:flex;align-items:center;justify-content:center;margin-bottom:14px}
.pagina-heredada .card-icon svg{color:var(--orange)}
.pagina-heredada .card h3{font-size:15px;font-weight:700;color:var(--navy);margin-bottom:8px;line-height:1.3}
.pagina-heredada .card p{font-size:13px;color:var(--gray-700);line-height:1.6}
.pagina-heredada .photo-block{border-radius:var(--radius-md);overflow:hidden;background:var(--gray-100);min-height:170px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;color:var(--gray-400);font-size:12px;text-align:center;padding:20px;border:1.5px dashed var(--gray-100)}
.pagina-heredada .stages{display:flex;flex-direction:column;gap:0}
.pagina-heredada .stage{display:flex;align-items:flex-start;gap:16px;padding:18px 0;border-bottom:1px solid rgba(255,255,255,0.1)}
.pagina-heredada .stage:last-child{border-bottom:none}
.pagina-heredada .stage-num{min-width:36px;height:36px;border-radius:50%;background:var(--orange);color:var(--white);font-size:13px;font-weight:800;display:flex;align-items:center;justify-content:center;flex-shrink:0;margin-top:2px}
.pagina-heredada .stage-body h4{font-size:14px;font-weight:700;color:var(--white);margin-bottom:3px}
.pagina-heredada .stage-body p{font-size:13px;color:rgba(255,255,255,0.65);line-height:1.55}
.pagina-heredada .cta-section{background:var(--navy);padding:48px 20px;text-align:center}
.pagina-heredada .cta-section h2{font-size:clamp(22px,6vw,32px);font-weight:800;color:var(--white);line-height:1.2;margin-bottom:12px}
.pagina-heredada .cta-section h2 span{color:var(--orange)}
.pagina-heredada .cta-section p{font-size:14px;color:rgba(255,255,255,0.7);margin-bottom:32px;line-height:1.65;max-width:440px;margin-left:auto;margin-right:auto}
.pagina-heredada .btn-group{display:flex;flex-direction:column;gap:12px;align-items:stretch;max-width:340px;margin:0 auto}
.pagina-heredada .cta-note{font-size:12px;color:rgba(255,255,255,0.45);margin-top:20px;line-height:1.6}
.pagina-heredada .divider{height:1px;background:var(--gray-100);margin:0 20px}
.pagina-heredada .joinchat{--ch:208;--cs:70%;--cl:33%;--bw:1}
